// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics.FilterPassEstimate;
import org.junit.jupiter.api.Test;

class LmdbHeuristicFilterPassCacheTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void structurallyEquivalentDetachedFiltersReuseOneEstimate() {
		LmdbHeuristicFilterPassCache cache = new LmdbHeuristicFilterPassCache(8, 1, 1024 * 1024L);
		LmdbHeuristicFilterPassCache.Revision revision = revision(17L);
		AtomicInteger computations = new AtomicInteger();
		Filter filter = filter(true);
		FilterPassEstimate expected = heuristic(0.25d);

		FilterPassEstimate first = cache.getOrCompute(filter, revision, () -> revision, () -> {
			computations.incrementAndGet();
			return expected;
		});
		FilterPassEstimate repeated = cache.getOrCompute(filter.clone(), revision, () -> revision, () -> {
			computations.incrementAndGet();
			return heuristic(0.75d);
		});

		assertSame(expected, first);
		assertSame(expected, repeated);
		assertEquals(1, computations.get());
		assertEquals(1L, cache.hits());
	}

	@Test
	void forcedFingerprintCollisionStillComparesTheCompleteFilter() {
		LmdbHeuristicFilterPassCache cache = new LmdbHeuristicFilterPassCache(
				8, 1, 1024 * 1024L, (revision, filter) -> 7L);
		LmdbHeuristicFilterPassCache.Revision revision = revision(17L);

		FilterPassEstimate first = cache.getOrCompute(
				filter(true), revision, () -> revision, () -> heuristic(0.25d));
		FilterPassEstimate second = cache.getOrCompute(
				filter(false), revision, () -> revision, () -> heuristic(0.75d));

		assertEquals(0.25d, first.getPassRatio(), 0.0d);
		assertEquals(0.75d, second.getPassRatio(), 0.0d);
		assertEquals(2, cache.entryCount());
	}

	@Test
	void revisionChangeDuringComputationPreventsPublication() {
		LmdbHeuristicFilterPassCache cache = new LmdbHeuristicFilterPassCache(8, 1, 1024 * 1024L);
		LmdbHeuristicFilterPassCache.Revision initial = revision(17L);
		AtomicReference<LmdbHeuristicFilterPassCache.Revision> current = new AtomicReference<>(initial);

		cache.getOrCompute(filter(true), initial, current::get, () -> {
			current.set(revision(18L));
			return heuristic(0.25d);
		});

		assertEquals(0, cache.entryCount());
	}

	@Test
	void oversizedDetachedFilterCompletesWithoutRetention() {
		LmdbHeuristicFilterPassCache cache = new LmdbHeuristicFilterPassCache(8, 1, 1L);
		LmdbHeuristicFilterPassCache.Revision revision = revision(17L);
		FilterPassEstimate expected = heuristic(0.25d);

		FilterPassEstimate result = cache.getOrCompute(
				filter(true), revision, () -> revision, () -> expected);

		assertSame(expected, result);
		assertEquals(0, cache.entryCount());
		assertEquals(0L, cache.retainedBytes());
	}

	private static Filter filter(boolean value) {
		StatementPattern pattern = new StatementPattern(
				Var.of("subject"), Var.of("predicate", VF.createIRI("urn:test:filter-cache")), Var.of("object"));
		return new Filter(pattern, new ValueConstant(VF.createLiteral(value)));
	}

	private static FilterPassEstimate heuristic(double ratio) {
		return new FilterPassEstimate(ratio, FilterPassEstimate.Source.HEURISTIC);
	}

	private static LmdbHeuristicFilterPassCache.Revision revision(long dataRevision) {
		return new LmdbHeuristicFilterPassCache.Revision(dataRevision, 2L, 3L, 4L, true);
	}
}
